}

private void StartDueWaves()
{
while (nextWaveIndex < stage.Waves.Count && stage.Waves[nextWaveIndex].StartTime <= elapsedTime)
{
var wave = new MonsterWave(spawnGroups, stage.Waves[nextWaveIndex], monsterFactory, spawnZones);
wave.Finished += OnWaveFinished;
runningWaves.Add(wave);
nextWaveIndex++;
}
}

// code/MonsterWaveDirector.cs:83-104
public void StartRound(int roundNumber)
{
StopRound();

List<WaveStageDef> stagesOfRound = FindStagesOfRound(roundNumber);
if (stagesOfRound.Count == 0)
{
// 끝 신호를 줄 스테이지가 없어 진행 중으로 두면 영원히 끝나지 않는다
Debug.LogWarning($"[MonsterWaveDirector] 라운드 {roundNumber} 스테이지 데이터 없음. 군중 소환 안 함", this);
return;
}

roundNo = roundNumber;
roundStages = stagesOfRound;
roundElapsedTime = 0f;
nextStageIndex = 0;
isRoundRunning = true;
pendingClearBonusStages = FindClearBonusStagesOfRound(roundNumber);
aliveMonsters.Clear();

StartDueStages();
}

